<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/workspace.php';$admin=require_role(['admin']);
$resourceMap=[
 'user'=>['table'=>'users','statuses'=>['active','suspended','pending_verification','deactivated']],
 'listing'=>['table'=>'produce_listings','statuses'=>['draft','active','paused','sold_out','archived']],
 'facility'=>['table'=>'storage_facilities','statuses'=>['draft','active','paused','archived']],
 'vehicle'=>['table'=>'vehicles','statuses'=>['available','busy','maintenance','inactive']],
];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=normalize_text($_POST['admin_action']??'',30);if($action==='save_category'){$id=(int)($_POST['id']??0);$name=normalize_text($_POST['name']??'',100);$description=normalize_text($_POST['description']??'',1000);if(strlen($name)<2)throw new RuntimeException('Enter a category name.');$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name)??'','-'));if($id)execute_query('UPDATE produce_categories SET name=:name,slug=:slug,description=:description,is_active=:active WHERE id=:id',['name'=>$name,'slug'=>$slug,'description'=>$description?:null,'active'=>(int)($_POST['is_active']??0),'id'=>$id]);else{db()->prepare('INSERT INTO produce_categories(name,slug,description,is_active) VALUES(:name,:slug,:description,:active)')->execute(['name'=>$name,'slug'=>$slug,'description'=>$description?:null,'active'=>(int)($_POST['is_active']??0)]);$id=(int)db()->lastInsertId();}audit_log((int)$admin['id'],'category_saved','produce_categories',$id);}elseif($action==='publish_announcement'){$title=normalize_text($_POST['title']??'',180);$body=trim((string)($_POST['body']??''));$role=normalize_text($_POST['audience_role']??'',40);if(strlen($title)<3||strlen($body)<5||($role!==''&&!in_array($role,['farmer','buyer','storage_provider','transport_provider','admin'],true)))throw new RuntimeException('Enter a title, message and valid audience.');db()->prepare('INSERT INTO announcements(author_id,title,body,audience_role,starts_at,is_active) VALUES(:author,:title,:body,:role,NOW(),1)')->execute(['author'=>$admin['id'],'title'=>$title,'body'=>$body,'role'=>$role?:null]);$announcementId=(int)db()->lastInsertId();$users=fetch_all('SELECT u.id FROM users u JOIN roles r ON r.id=u.role_id WHERE u.status="active"'.($role!==''?' AND r.slug=:role':''),$role!==''?['role'=>$role]:[]);foreach($users as $recipient)create_notification((int)$recipient['id'],'admin_announcement',$title,normalize_text($body,500),'notifications.php','announcement',$announcementId);audit_log((int)$admin['id'],'announcement_published','announcements',$announcementId);}elseif($action==='set_status'){$type=normalize_text($_POST['resource_type']??'',30);$id=(int)($_POST['resource_id']??0);$status=normalize_text($_POST['status']??'',30);$definition=$resourceMap[$type]??null;if(!$definition||$id<1||!in_array($status,$definition['statuses'],true))throw new RuntimeException('Choose a valid resource and status.');$statement=db()->prepare('UPDATE '.$definition['table'].' SET status=:status WHERE id=:id');$statement->execute(['status'=>$status,'id'=>$id]);if($statement->rowCount()<1)throw new RuntimeException('That resource was not found or already has this status.');audit_log((int)$admin['id'],'admin_status_changed',$definition['table'],$id,['status'=>$status]);}else throw new RuntimeException('That administrator action is unavailable.');flash('success','Administrator change saved.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('admin/management.php');}
$categories=fetch_all('SELECT * FROM produce_categories ORDER BY name');$announcements=fetch_all('SELECT a.*,u.full_name FROM announcements a JOIN users u ON u.id=a.author_id ORDER BY a.created_at DESC LIMIT 20');$registers=[
'user'=>fetch_all('SELECT u.id,u.full_name AS label,r.name AS context,u.status FROM users u JOIN roles r ON r.id=u.role_id ORDER BY u.created_at DESC LIMIT 25'),
'listing'=>fetch_all('SELECT pl.id,pl.title AS label,u.full_name AS context,pl.status FROM produce_listings pl JOIN users u ON u.id=pl.farmer_id ORDER BY pl.created_at DESC LIMIT 25'),
'facility'=>fetch_all('SELECT sf.id,sf.name AS label,u.full_name AS context,sf.status FROM storage_facilities sf JOIN storage_providers sp ON sp.id=sf.provider_id JOIN users u ON u.id=sp.user_id ORDER BY sf.created_at DESC LIMIT 25'),
'vehicle'=>fetch_all('SELECT v.id,v.registration_number AS label,v.vehicle_type AS context,v.status FROM vehicles v ORDER BY v.created_at DESC LIMIT 25'),
];$workflowOversight=['Offers'=>fetch_all('SELECT CONCAT("Offer #",o.id) AS label,pl.title AS context,o.status FROM offers o JOIN produce_listings pl ON pl.id=o.listing_id ORDER BY o.created_at DESC LIMIT 25'),'Storage bookings'=>fetch_all('SELECT sb.reference_code AS label,sf.name AS context,sb.status FROM storage_bookings sb JOIN storage_facilities sf ON sf.id=sb.facility_id ORDER BY sb.created_at DESC LIMIT 25'),'Transport requests'=>fetch_all('SELECT tr.reference_code AS label,tr.produce_description AS context,tr.status FROM transport_requests tr ORDER BY tr.created_at DESC LIMIT 25')];workspace_open('Administrator operations','management');
?>
<section class="workspace-section"><div class="workspace-section-header"><div><h2>Produce categories</h2><p>Add, rename, describe, activate or retire extensible marketplace categories.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="admin_action" value="save_category"><label>Name<input name="name" maxlength="100" required></label><label>Description<input name="description" maxlength="1000"></label><label><input type="checkbox" name="is_active" value="1" checked> Active</label><button class="button button-primary" type="submit">Add category</button></form><div class="category-admin-list"><?php foreach($categories as $category):?><form method="post" class="compact-action"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="admin_action" value="save_category"><input type="hidden" name="id" value="<?= (int)$category['id'] ?>"><input name="name" maxlength="100" required value="<?= e($category['name']) ?>"><input name="description" maxlength="1000" value="<?= e($category['description']??'') ?>"><label><input type="checkbox" name="is_active" value="1" <?= $category['is_active']?'checked':'' ?>> Active</label><button class="button button-quiet" type="submit">Save category</button></form><?php endforeach;?></div></section>
<section class="workspace-section"><div class="workspace-section-header"><div><h2>Publish announcement</h2><p>Creates a real in-app notification for the selected audience.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="admin_action" value="publish_announcement"><label>Title<input name="title" maxlength="180" required></label><label>Audience<select name="audience_role"><option value="">All active users</option><option value="farmer">Farmers</option><option value="buyer">Buyers</option><option value="storage_provider">Storage providers</option><option value="transport_provider">Transport providers</option></select></label><label>Announcement<textarea name="body" maxlength="3000" required></textarea></label><button class="button button-primary" type="submit">Publish announcement</button></form></section>
<section class="workspace-section"><div class="workspace-section-header"><div><h2>Announcement register</h2><p>Published content remains accountable and can be withdrawn without deleting its audit trail.</p></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Announcement</th><th>Audience</th><th>Author</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if($announcements===[]):?><tr><td colspan="5">No announcements have been published.</td></tr><?php else:foreach($announcements as $announcement):?><tr><td><strong><?= e($announcement['title']) ?></strong><br><span class="muted"><?= e(normalize_text($announcement['body'],180)) ?></span></td><td><?= e($announcement['audience_role']?order_status_label($announcement['audience_role']):'All active users') ?></td><td><?= e($announcement['full_name']) ?></td><td><span class="status-pill <?= $announcement['is_active']?'active':'inactive' ?>"><?= $announcement['is_active']?'Active':'Withdrawn' ?></span></td><td><form method="post" action="<?= e(app_url('admin/announcement-status.php')) ?>"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="announcement_id" value="<?= (int)$announcement['id'] ?>"><input type="hidden" name="is_active" value="<?= $announcement['is_active']?0:1 ?>"><button class="button button-quiet" type="submit"><?= $announcement['is_active']?'Withdraw':'Republish' ?></button></form></td></tr><?php endforeach;endif;?></tbody></table></div></section>
<?php foreach($registers as $type=>$rows):?><section class="workspace-section"><div class="workspace-section-header"><div><h2><?= e(ucwords(str_replace('_',' ',$type))) ?> register</h2><p>Latest 25 records; status changes are validated and audited.</p></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Record</th><th>Context</th><th>Status</th><th>Administrator action</th></tr></thead><tbody><?php if($rows===[]):?><tr><td colspan="4">No records in this register yet.</td></tr><?php else:foreach($rows as $row):?><tr><td><?= e($row['label']) ?></td><td><?= e($row['context']) ?></td><td><span class="status-pill <?= e($row['status']) ?>"><?= e(order_status_label($row['status'])) ?></span></td><td><form method="post" class="compact-action"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="admin_action" value="set_status"><input type="hidden" name="resource_type" value="<?= e($type) ?>"><input type="hidden" name="resource_id" value="<?= (int)$row['id'] ?>"><select name="status" required><?php foreach($resourceMap[$type]['statuses'] as $status):?><option value="<?= e($status) ?>" <?= $row['status']===$status?'selected':'' ?>><?= e(order_status_label($status)) ?></option><?php endforeach;?></select><button class="button button-quiet" type="submit">Save</button></form></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php endforeach;?>
<?php foreach($workflowOversight as $title=>$rows):?><section class="workspace-section"><div class="workspace-section-header"><div><h2><?= e($title) ?> oversight</h2><p>Commercial lifecycle changes remain in their protected participant/provider workflow so capacity, quantities, assignments, notifications, and history stay consistent.</p></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Record</th><th>Context</th><th>Status</th></tr></thead><tbody><?php if($rows===[]):?><tr><td colspan="3">No records yet.</td></tr><?php else:foreach($rows as $row):?><tr><td><?= e($row['label']) ?></td><td><?= e($row['context']) ?></td><td><span class="status-pill <?= e($row['status']) ?>"><?= e(order_status_label($row['status'])) ?></span></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php endforeach;?>
